        var t = String(o.textContent || "").trim().toLowerCase(), c = t.charAt(0), k;
        if (!(c === "-" || c === "—" || c === "–" || c === "." || c === "…")) { return false; }
        for (k = 0; k < PH_WORDS.length; k++) { if (t.indexOf(PH_WORDS[k]) >= 0) { return true; } }
        for (k = 0; k < t.length; k++) { if ("-—–.… ".indexOf(t.charAt(k)) < 0) { return false; } }
        return true;
    }
    function clear(sel, ph) {
        if (ph) { sel.value = ph.value; } else { sel.selectedIndex = -1; }
    }
    function hasValue(sel, v) {
        for (var i = 0; i < sel.options.length; i++) { if (sel.options[i].value === v) { return true; } }
        return false;
    }

    /* 8. Text follows the language. The tables are the sim's own (vcI18n on the platform, .trans in the
       Open player). A string is replaced only when it is another language's value for a key the current
       language also has, and never when it is also a value of the current language itself. */
    var trCache = { lang: null, maps: null };
    function rawLang() {
        var l = "";
        try { if (window.vcI18n && window.vcI18n._lang) { l = window.vcI18n._lang; } } catch (e) {}
        try { if (!l && sim() && sim().lang) { l = sim().lang; } } catch (e) {}
        if (!l) { l = document.documentElement.lang || "en"; }
        return String(l).toLowerCase().slice(0, 2);
    }
    function tables() {
        try { if (window.vcI18n && window.vcI18n._translations && typeof window.vcI18n._translations === "object") { var t = window.vcI18n._translations; for (var k in t) { if (t[k] && typeof t[k] === "object") { return t; } } } } catch (e) {}
        try { var f = sim(); if (f && f.trans && typeof f.trans === "object") { return f.trans; } } catch (e) {}
