            if (d.round3) { set('r3_outlier', d.round3.outlier); set('r3_scope', d.round3.scope); set('r3_check', d.round3.check); }
            if (d.round4) { set('r4_reco', d.round4.reco); set('r4_format', d.round4.format); set('r4_risk', d.round4.risk); }
        }

        _t(key, vars) {
            return window.mySimulation ? window.mySimulation.t(key, vars) : key;
        }

        _cl(key, fallback) {
            var s = this._t(key);
            return s === key ? fallback : s;
        }

        _lang() {
            return (window.mySimulation && window.mySimulation.language === 'en') ? 'en' : 'es';
        }

        _fmtNum(v, dec) {
            var n = Number(v) || 0;
            var neg = n < 0;
            var f = Math.abs(n).toFixed(dec);
            var parts = f.split('.');
            var s = parts[0];
            var out = '';
            var th = this._lang() === 'en' ? ',' : '.';
            var dp = this._lang() === 'en' ? '.' : ',';
            while (s.length > 3) { out = th + s.slice(-3) + out; s = s.slice(0, -3); }
            out = s + out;
            if (parts.length > 1) { out = out + dp + parts[1]; }
            return (neg && Number(f) !== 0 ? '−' : '') + out;
        }

        _fmtMoney(v) {
            var n = Math.round(Number(v) || 0);
            var body = this._fmtNum(Math.abs(n), 0);
            if (this._lang() === 'en') { return (n < 0 ? '−€' : '€') + body; }
            return (n < 0 ? '−' : '') + body + ' €';
        }

        _optName(k) {
            return this._t('opt_short_' + k);
        }

        _updateBriefing(state) {
            var cur = (state && state.currentPeriod) || 1;
            var maxP = (state && state.maxPeriods) || this.ROUNDS.length;
            var done = (state && state.history) ? state.history.length : 0;
            var finished = done >= maxP || cur > this.ROUNDS.length;
            var i, panel;
            for (i = 0; i < this.ROUNDS.length; i++) {
                panel = document.getElementById(this.ROUNDS[i].panel);
                if (panel) { panel.style.display = (!finished && (i + 1) === cur) ? 'block' : 'none'; }
            }
            var actions = document.getElementById('actionsRow');
            if (actions) { actions.style.display = finished ? 'none' : 'flex'; }
            var idx = Math.min(cur, this.ROUNDS.length) - 1;
            var nameEl = document.getElementById('roundName');
            if (nameEl) { nameEl.textContent = finished ? this._t('round_done') : this._t(this.ROUNDS[idx].nameKey); }
            var briefEl = document.getElementById('briefingText');
            if (briefEl) { briefEl.innerHTML = finished ? this._t('brief_done') : this._t(this.ROUNDS[idx].briefKey); }
            this._renderDynamic(state);
        }

        _renderDynamic(state) {
            var ds = (state && state.domainState) || {};
            var days = ds.days || [];
            var rounds = ds.rounds || [];
            var sEl = document.getElementById('semesterText');
            if (sEl) { sEl.innerHTML = days.length ? this._dayHtml(ds, days[days.length - 1]) : this._t('sem_pending'); }
            var fbEl = document.getElementById('feedbackText');
            if (fbEl) {
                fbEl.classList.remove('ea2146-warn');
                var last = rounds.length ? rounds[rounds.length - 1] : null;
                if (!last) { fbEl.innerHTML = this._t('feedback_empty'); }
                else {
                    fbEl.innerHTML = this._feedbackHtml(ds, last);
                    if (last.verdictKey !== 'ok') { fbEl.classList.add('ea2146-warn'); }
                }
            }
        }

        _dayHtml(ds, w) {
            var v = {
                hours: this._fmtNum(w.hours, 1), budget: this._fmtNum(C.BUDGET[w.t - 1], 1), over: this._fmtNum(w.over, 1),
                err: this._fmtMoney(w.err), best: this._optName(w.best),
                sC: this._fmtMoney(w.app.C), sN: this._fmtMoney(w.app.N), sS: this._fmtMoney(w.app.S), sO: this._fmtMoney(w.app.O),
                vN: this._fmtMoney(w.V.norte), vO: this._fmtMoney(w.V.online), vM: this._fmtMoney(w.V.minimum),
                small: this._fmtNum(w.small, 0)
            };
            var html = this._t('sem_body', v);
            html += '<span class="ea2146-cases">' + this._t('s_sales', v) + '</span>';
            html += '<span class="ea2146-cases">' + this._t('s_cases', v) + '</span>';
            if (w.t === 3 && w.excluded > 0) { html += '<span class="ea2146-reveal">' + this._t('s_fit', { excluded: this._fmtMoney(w.excluded) }) + '</span>'; }
            if (w.t === 4) {
                html += '<span class="ea2146-reveal">' + this._t('s_decision', {
                    reco: this._optName(w.reco), dv: this._fmtMoney(w.dv),
                    tN: this._fmtMoney(TV.norte), tO: this._fmtMoney(TV.online), tM: this._fmtMoney(TV.minimum)
                }) + '</span>';
            }
            var i;
            var keys = ds.capKeys || [];
            for (i = 0; i < keys.length; i++) { html += '<span class="ea2146-reveal">' + this._t(keys[i]) + '</span>'; }
            return html;
        }

        _feedbackHtml(ds, r) {
            var v = { pts: this._fmtNum(Math.round(r.pts * 10) / 10, 1) };
            return '<strong>' + this._t('fb_points', v) + '</strong> ' + this._t('fb_r' + r.period + '_' + r.verdictKey, v);
        }

        _readSelect(id, allowed) {
            var el = document.getElementById(id);
            if (!el) { return null; }
            var val = String(el.value);
            if (allowed.indexOf(val) === -1) { return null; }
            return val;
        }

        validateDecisions(decisions) {
            var sim = window.mySimulation;
            var state = sim && sim.state ? sim.state : { currentPeriod: 1, history: [] };
            var period = state.currentPeriod || 1;
            var done = state.history ? state.history.length : 0;
            var warn = function(key) {
                sim.uiManager.showNotification(sim.t(key), 'warning');
                return false;
            };
            if (done >= this.ROUNDS.length || period > this.ROUNDS.length) { return warn('warn_finished'); }
            if (period === 1) {
                var dupes = this._readSelect('r1_dupes', CTRL.round1.dupes);
                var returns = this._readSelect('r1_returns', CTRL.round1.returns);
                var online = this._readSelect('r1_online', CTRL.round1.online);
                if (!dupes || !returns || !online) { return warn('warn_r1'); }
                decisions.round1 = { dupes: dupes, returns: returns, online: online };
                return true;
            }
            if (period === 2) {
                var kpi = this._readSelect('r2_kpi', CTRL.round2.kpi);
                var costs = this._readSelect('r2_costs', CTRL.round2.costs);
                var customers = this._readSelect('r2_customers', CTRL.round2.customers);
                if (!kpi || !costs || !customers) { return warn('warn_r2'); }
                decisions.round2 = { kpi: kpi, costs: costs, customers: customers };
                return true;
            }
            if (period === 3) {
                var outlier = this._readSelect('r3_outlier', CTRL.round3.outlier);
                var scope = this._readSelect('r3_scope', CTRL.round3.scope);
                var check = this._readSelect('r3_check', CTRL.round3.check);
                if (!outlier || !scope || !check) { return warn('warn_r3'); }
                decisions.round3 = { outlier: outlier, scope: scope, check: check };
                return true;
            }
            if (period === 4) {
                var reco = this._readSelect('r4_reco', CTRL.round4.reco);
                var format = this._readSelect('r4_format', CTRL.round4.format);
                var risk = this._readSelect('r4_risk', CTRL.round4.risk);
                if (!reco || !format || !risk) { return warn('warn_r4'); }
                decisions.round4 = { reco: reco, format: format, risk: risk };
                return true;
            }
            return warn('warn_finished');
        }

        calculateResults(state) {
            var out = this._computeRound(state);
            var self = this;
            setTimeout(function() { self._updateBriefing(window.mySimulation.state); }, 400);
            return out;
        }

        // Round model. Every carried quantity is rebuilt from the decision history, so a resubmit is idempotent.
        _computeRound(state) {
            var ds = state.domainState;
            var raw = state.decisions || {};
            var period = state.currentPeriod || 1;
            var saved = ds.dec || {};
            var d = {};
            var k;
            for (k = 1; k <= period; k++) {
                if (raw['round' + k]) { d['round' + k] = raw['round' + k]; }
                else if (k < period && saved['round' + k]) { d['round' + k] = saved['round' + k]; }
            }
            ds.dec = JSON.parse(JSON.stringify(d));
            var rounds = [];
            var days = [];
            var total = 0.0;
            var fit = false;
            var cumOver = 0.0;
            var r, known, pic, err, h, over, tpts, rub, first, dv, pts, cap, capF, capS, b;
            for (r = 1; r <= period; r++) {
                known = this._known(d, r);
                pic = this._picture(known);
                err = errOf(pic.V);
                h = this._hours(known, r);
                over = Math.max(0.0, h - C.BUDGET[r - 1]);
                cumOver += over;
                tpts = 5.0 * clamp(1.0 - over / C.OVER_ZERO, 0.0, 1.0);
                rub = this._rubric(known, r, pic);
                dv = null;
                if (r < 4) {
                    first = 5.0 * clamp(1.0 - err / C.ERR_ZERO, 0.0, 1.0);
                } else {
                    dv = this._decisionValue(known);
                    first = 10.0 * clamp((dv - C.VAL_LO) / (C.VAL_HI - C.VAL_LO), 0.0, 1.0);
                    tpts = 0.0;
                }
                pts = rub + first + tpts;
                total += pts;
                if (r >= 3 && known.round3.scope === 'fit') { fit = true; }
                capF = fit ? Math.max(C.CAP_FLOOR, C.CAP_BASE - C.CAP_ERR * err / 1000.0) : 100.0;
                capS = 100.0;
                if (r === 4 && !this._supported(known, pic)) {
                    b = bestOf(pic.V);
                    capS = Math.max(C.SUP_FLOOR, C.SUP_BASE - C.SUP_GAP * (pic.V[b] - pic.V[known.round4.reco]) / 1000.0);
                }
                cap = Math.min(capF, capS);
                days.push({
                    t: r, hours: h, over: over, err: err, V: pic.V, best: bestOf(pic.V), app: pic.app, small: pic.small,
                    excluded: pic.excluded, dv: dv, reco: (r === 4) ? known.round4.reco : null
                });
                rounds.push({ period: r, rub: rub, outp: first + tpts, pts: pts, verdictKey: this._verdict(known, r, pic) });
            }
            ds.rounds = rounds;
            ds.days = days;
            ds.cumOver = cumOver;
            ds.fit = fit;
            ds.total = total;
            ds.cap = cap;
            ds.capF = capF;
            ds.capS = capS;
            var score = this._composite(ds);
            ds.capKeys = [];
            if (capF < 100 && total > capF) { ds.capKeys.push('cap_fit'); }
            if (capS < 100 && total > capS) { ds.capKeys.push('cap_support'); }
            ds.performance = { overallScore: score };
            ds.performanceTier = this._tier(score);
            ds.scoreHistory = (ds.scoreHistory || []).slice(0, period - 1);
            ds.scoreHistory[period - 1] = score;
            ds.scoreHistory.length = period;
            var last = days[days.length - 1];
            return {
                period: period,
                roundPoints: Math.round(rounds[period - 1].pts * 10) / 10,
                hours: Math.round(last.hours * 10) / 10,
                err: Math.round(last.err),
                best: last.best,
                score: score,
                overallScore: score
            };
        }

        _known(d, r) {
            var out = {};
            var k;
            for (k = 1; k <= r; k++) { if (d['round' + k]) { out['round' + k] = d['round' + k]; } }
            return out;
        }

        // The business case as it stands with the decisions taken so far (later rounds untreated).
        _picture(dec) {
            var r1 = dec.round1;
            var r2 = dec.round2 || UNTREATED.round2;
            var r3 = dec.round3 || UNTREATED.round3;
            var T = C.S_TRUE;
            var app = { C: T.C, N: T.N, S: T.S, O: T.O };
            var dup = C.DUP[r1.dupes];
            app.N += dup.N;
            app.S += dup.S;
            if (r1.returns === 'delete') {
                app.C += C.RET.C;
                app.N += C.RET.N;
                app.S += C.RET.S;
                app.O += C.O_RET;
            } else if (r1.returns === 'keep') {
                app.O -= C.O_RET;
            }
            if (r1.online === 'asis') {
                var gross = C.O_GROSS - (r1.returns === 'keep' ? C.O_RET : 0.0);
                app.O += C.VAT * gross + C.TESTS;
            }
            if (r1.online === 'asis' || r1.online === 'net') { app.O -= C.O_Q4; }
            var cat = C.CATCH[r3.check];
            app.C = T.C + (app.C - T.C) * (1.0 - cat);
            app.N = T.N + (app.N - T.N) * (1.0 - cat);
            app.S = T.S + (app.S - T.S) * (1.0 - cat);
            app.O = T.O + (app.O - T.O) * (1.0 - cat);
            var q4 = (r1.online === 'full') ? C.O_Q4 : C.O_Q4 * cat;
            var novdec = C.O_NOVDEC * q4 / C.O_Q4;
            var excluded = (r3.scope === 'fit') ? novdec : 0.0;
            var sO = app.O - excluded;
            var sN = app.N - ((r3.outlier === 'remove' || r3.outlier === 'separate') ? C.HOTEL : 0.0);
            var m = C.M[r2.kpi];
            var mR = m.R, mO = m.O;
            var fR = 1.0, fO = 1.0;
            if (r2.costs === 'drop') { fR = 1.0 - C.DROP.R; fO = 1.0 - C.DROP.O; }
            else if (r2.costs === 'avg') { mO -= C.AVG_O; }
            var small = C.SMALL[r2.customers];
            var V = {
                norte: C.U_N * sN * fR * mR - C.K_N,
                online: C.U_O * sO * fO * mO - C.K_O,
                minimum: C.SAVE_M * small - C.K_M
            };
            return { app: app, sN: sN, sO: sO, small: small, V: V, excluded: excluded };
        }

        _hours(dec, r) {
            var rd = dec['round' + r];
            var H = C['H' + r];
            var s = 0.0;
            var key;
            for (key in rd) { if (Object.prototype.hasOwnProperty.call(rd, key)) { s += H[key][rd[key]]; } }
            return s;
        }

        _supported(dec, pic) {
            return dec.round3.scope !== 'norte' && dec.round4.reco === bestOf(pic.V);
        }

        _recoPoints(dec, pic) {
            var reco = dec.round4.reco;
            if (dec.round3.scope === 'norte') { return reco === 'norte' ? C.RECO_NORTE_ONLY : C.RECO_BAD; }
            return reco === bestOf(pic.V) ? C.RECO_OK : C.RECO_BAD;
        }

        _rubric(dec, r, pic) {
            var P = C.PTS;
            var d;
            if (r === 1) {
                d = dec.round1;
                return P.dupes1[d.dupes] + P.returns1[d.returns] + P.online1[d.online];
            }
            if (r === 2) {
                d = dec.round2;
                return P.kpi2[d.kpi] + P.costs2[d.costs] + P.customers2[d.customers];
            }
            if (r === 3) {
                d = dec.round3;
                return P.outlier3[d.outlier] + P.scope3[d.scope] + P.check3[d.check];
            }
            d = dec.round4;
            return this._recoPoints(dec, pic) + P.format4[d.format] + P.risk4[d.risk];
        }

        _decisionValue(dec) {
            var r4 = dec.round4;
            var v = TV[r4.reco];
            if (r4.risk === 'pilot') { v = C.PILOT_OWN * v + (1.0 - C.PILOT_OWN) * TV[BEST] - C.PILOT_COST; }
            return v;
        }

        _verdict(dec, r, pic) {
            var d;
            if (r === 1) {
                d = dec.round1;
                if (d.dupes === 'none' && d.online === 'asis') { return 'raw'; }
                if (d.online !== 'full') { return 'q4'; }
                if (d.returns !== 'match') { return 'returns'; }
                if (d.dupes !== 'key') { return 'dupes'; }
                return 'ok';
            }
            if (r === 2) {
                d = dec.round2;
                if (d.kpi === 'sales') { return 'sales'; }
                if (d.costs === 'drop') { return 'drop'; }
                if (d.customers === 'names') { return 'names'; }
                if (d.kpi === 'margin') { return 'margin'; }
                if (d.costs === 'invoices') { return 'slow'; }
                return 'ok';
            }
            if (r === 3) {
                d = dec.round3;
                if (d.scope === 'fit') { return 'fit'; }
                if (d.scope === 'norte') { return 'narrow'; }
                if (d.outlier === 'keep') { return 'outlier'; }
                if (d.check === 'none') { return 'nocheck'; }
                if (d.outlier === 'remove') { return 'silent'; }
                return 'ok';
            }
            d = dec.round4;
            if (dec.round3.scope === 'norte') { return 'narrow'; }
            if (d.reco !== bestOf(pic.V)) { return 'unsupported'; }
            if (d.reco !== BEST) { return 'wrongdata'; }
            if (d.format !== 'onepage') { return 'format'; }
            if (d.risk === 'point') { return 'point'; }
            return 'ok';
        }

        _composite(ds) {
            var total = Math.min((ds && typeof ds.cap === 'number') ? ds.cap : 100, (ds && ds.total) || 0);
            return Math.max(0, Math.min(100, Math.round(total)));
        }

        _tier(score) {
            if (score >= 75) { return 'excellent'; }
            if (score >= 55) { return 'good'; }
            return 'beginner';
        }

        setupUI(uiManager) {
            var self = this;
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('scoreDisplay', 'domainState.performance.overallScore', function(v) { return (typeof v === 'number') ? String(v) : '0'; });
            uiManager.bind('hoursDisplay', 'domainState', function(ds) {
                var ws = (ds && ds.days) || [];
                return ws.length ? self._fmtNum(ws[ws.length - 1].hours, 1) : '—';
            });
            uiManager.bind('errDisplay', 'domainState', function(ds) {
                var ws = (ds && ds.days) || [];
                return ws.length ? self._fmtMoney(ws[ws.length - 1].err) : '—';
            });
            uiManager.bind('bestDisplay', 'domainState', function(ds) {
                var ws = (ds && ds.days) || [];
                return ws.length ? self._optName(ws[ws.length - 1].best) : '—';
            });
            uiManager.bind('overDisplay', 'domainState', function(ds) {
                return self._fmtNum((ds && ds.cumOver) || 0, 1);
            });
            uiManager.bind('valueDisplay', 'domainState', function(ds) {
                var ws = (ds && ds.days) || [];
                var w = ws.length ? ws[ws.length - 1] : null;
                return (w && w.t === 4) ? self._fmtMoney(w.dv) : '—';
            });
        }

        getChartConfig() {
            var t = this._t.bind(this);
            var sp = t('s_short');
            return {
                errChart: {
                    type: 'bar',
                    data: {
                        labels: [sp + '1', sp + '2', sp + '3', sp + '4'],
                        datasets: [{ label: t('chart_dataset'), data: [0, 0, 0, 0], backgroundColor: ['#1f4a66', '#1f4a66', '#1f4a66', '#8a3b12'], borderWidth: 0 }]
                    },
                    options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { display: false } }, scales: { y: { ticks: { color: '#2b3440' } }, x: { ticks: { color: '#2b3440' } } } }
                }
            };
        }

        getChartData(state) {
            var ds = (state && state.domainState) || {};
            var ws = ds.days || [];
            var hist = ds.scoreHistory || [];
            var data = [0, 0, 0, 0];
            var sp = this._t('s_short');
            var i;
            for (i = 0; i < ws.length && i < 4; i++) { data[i] = Math.round(ws[i].err); }
            return {
                errChart: {
                    labels: [sp + '1', sp + '2', sp + '3', sp + '4'],
                    datasets: [{ data: data, label: this._t('chart_dataset') + (hist.length ? ' · ' + sp + hist.length : '') }]
                }
            };
        }

        getHistoryTableConfig() {
            var self = this;
            return [
                { key: 'results.roundPoints', label: 'Points', i18nKey: 'col_points' },
                { key: 'results.hours', label: 'Hours', i18nKey: 'col_hours', formatter: function(v) { return self._fmtNum(v, 1); } },
                { key: 'results.err', label: 'Business-case deviation', i18nKey: 'col_err', formatter: function(v) { return self._fmtMoney(v); } },
                { key: 'results.best', label: 'Option her data point to', i18nKey: 'col_best', formatter: function(v) { return self._optName(v); } },
                { key: 'results.score', label: 'Score', i18nKey: 'col_score' }
            ];
        }

        getHint(state, results) {
            var ds = state.domainState || {};
            var r = (ds.rounds || [])[(results.period || 1) - 1];
            if (!r) { return null; }
            return this._t('hint_r' + r.period + '_' + r.verdictKey);
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) { return {}; }
            var ds = window.mySimulation.state.domainState;
            var ws = ds.days || [];
            var score = this._composite(ds);
            var performance = 'Beginner';
            if (score >= 55) { performance = 'Good'; }
            if (score >= 75) { performance = 'Excellent'; }
            var last = ws.length ? ws[ws.length - 1] : null;
            var insights = [];
            insights.push((last && last.err <= 1500) ? this._t('insight_err_ok') : this._t('insight_err_bad'));
            insights.push((last && last.best === BEST) ? this._t('insight_best_ok') : this._t('insight_best_bad'));
            insights.push(ds.fit ? this._t('insight_fit_bad') : this._t('insight_fit_ok'));
            insights.push(((ds.cumOver || 0) > 2) ? this._t('insight_time_bad') : this._t('insight_time_ok'));
            insights.push(this._t('insight_next'));
            return {
                composite: score,
                overallScore: score,
                totalScore: score,
                score: score,
                err: last ? last.err : 0,
                dv: (last && last.dv !== null) ? last.dv : 0,
                reco: last ? last.reco : null,
                cumOver: ds.cumOver || 0,
                rounds: (ds.scoreHistory || []).length,
                performance: performance,
                performanceKey: performance.toLowerCase(),
                performanceLabel: this._cl('grade_' + performance.toLowerCase(), performance),
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore : 0;
            var items = (s.insights || []).map(function(x) { return '<li>' + x + '</li>'; }).join('');
            return '<div class="ea2146-cm">'
                + '<div class="ea2146-cm-score">' + score + '<span class="ea2146-cm-max">/100</span></div>'
                + '<div class="ea2146-cm-verdict">' + (s.performanceLabel || s.performance || '') + '</div>'
